// Healthcare Administration Practice Test 1. Original questions written for Valus from the HOSA 2026–27
// test plan, slightly harder than the sample items: applying management models to health care cases.
import {q, mix} from './q.js';
const SK='Burns, Bradley & Weiner, Shortell & Kaluzny’s Health Care Management', BUCH='Buchbinder, Introduction to Health Care Management';
const GLOB='Globalization of Health Care Delivery Systems and Challenges', LEAD='Leadership & Management Framework', ORG='Organization Design & Coordination', MOT='Motivating People and Conflict Management', TEAM='Teams & Team Effectiveness', COMM='Communication', QUAL='Improving Quality', STRAT='Strategy & Achieving Mission', POL='Health Policy & Regulation', CONS='Consumerism & Ethics';

export default {
 id:'healthcare-administration-1',
 event:'Healthcare Administration',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Shortell & Kaluzny’s Health Care Management: Organization Design and Behavior and Buchbinder’s Introduction to Health Care Management',
 plan:[{area:GLOB,weight:10},{area:LEAD,weight:10},{area:ORG,weight:10},{area:MOT,weight:10},{area:TEAM,weight:10},{area:COMM,weight:10},{area:QUAL,weight:10},{area:STRAT,weight:10},{area:POL,weight:10},{area:CONS,weight:10}],
 questions:mix([
  q(GLOB,'In which country does a single, government-run insurance plan in each province pay for medically necessary care delivered by private providers?','Canada',['United States','Germany','Switzerland'],'B','Canada’s single-payer system uses public insurance; most physicians are in private practice. Germany uses multiple nonprofit sickness funds.',BUCH),
  q(GLOB,'Germany’s system, in which employers and employees fund nonprofit “sickness funds,” is an example of which model?','The Bismarck model',['The Beveridge model','The out-of-pocket model','The national health insurance model'],'D','The Bismarck model uses insurance funds financed through payroll. The Beveridge model (like the UK) is government-financed and largely government-delivered.',BUCH),
  q(GLOB,'Compared with other high-income countries, how does U.S. health spending as a share of GDP rank?','It is the highest',['It is the lowest','It is about average','It cannot be measured'],'A','The United States spends about 17–18% of GDP on health care, far more than peer nations, yet has lower life expectancy than many of them.',BUCH),
  q(GLOB,'What does “universal health coverage” mean?','Everyone gets needed care without hardship',['Every country uses the same insurance company','All care is provided free in hospitals','Only children receive coverage'],'C','Universal coverage can be achieved through different models, including single-payer, multi-payer and mixed systems.',BUCH),
  q(GLOB,'A patient travels abroad for a knee replacement because it costs less there. What is this called?','Medical tourism',['Telehealth','Managed care','Outsourcing'],'B','Medical tourism raises questions about quality standards, continuity of care and handling complications after the patient returns home.',BUCH),
  q(LEAD,'A hospital CEO inspires staff with a shared vision and encourages them to exceed expectations. Which leadership style is this?','Transformational leadership',['Transactional leadership','Laissez-faire leadership','Autocratic leadership'],'D','Transformational leaders motivate through vision, inspiration and individual consideration. Transactional leaders rely on rewards and corrective action.',SK),
  q(LEAD,'A manager focuses on supporting the growth and well-being of staff and puts their needs first. Which style is this?','Servant leadership',['Autocratic leadership','Transactional leadership','Bureaucratic leadership'],'A','Servant leaders emphasize listening, empathy and developing others, which can build trust and engagement.',SK),
  q(LEAD,'Which four functions are classically used to describe the work of managers?','Planning, organizing, leading and controlling',['Hiring, firing, billing and coding','Selling, marketing, pricing and promoting','Diagnosing, treating, discharging and following up'],'C','These functions describe what managers do: set goals, arrange resources, direct people and monitor performance.',BUCH),
  q(LEAD,'A manager gives detailed direction to a new employee but lets an experienced employee work independently. Which leadership approach is this?','Situational leadership',['Laissez-faire leadership','Trait theory','Great man theory'],'B','Situational leadership adapts the leader’s style to each follower’s competence and commitment.',SK),
  q(LEAD,'Which leadership skill involves recognizing and managing one’s own emotions and those of others?','Emotional intelligence',['Technical expertise','Financial forecasting','Strategic positioning'],'D','Emotional intelligence includes self-awareness, self-regulation, empathy and social skill, and is linked to effective leadership.',SK),
  q(ORG,'In a matrix organization, what is unique about employees’ reporting relationships?','They may report to two managers',['They report to no one','They report only to the CEO','They report only to their patients'],'A','Matrix structures improve coordination across departments but can create confusion and conflict over two bosses.',SK),
  q(ORG,'A hospital system buys physician practices, home health agencies and a nursing home. What type of integration is this?','Vertical integration',['Horizontal integration','Divestiture','Outsourcing'],'C','Vertical integration links different levels of care in one system. Horizontal integration combines organizations at the same level, such as two hospitals.',SK),
  q(ORG,'Two community hospitals in the same city merge into one system. What is this?','Horizontal integration',['Vertical integration','A joint venture with a supplier','A franchise'],'B','Horizontal integration can increase market share and economies of scale but may reduce competition.',SK),
  q(ORG,'What does “span of control” refer to?','Number of direct reports per manager',['The area of a hospital’s campus in acres','The budget a department controls','The number of services offered'],'D','Wider spans fit routine work and experienced staff; narrower spans allow closer supervision.',BUCH),
  q(ORG,'An organization lets unit managers make many decisions without approval from top leadership. This structure is:','Decentralized',['Centralized','Bureaucratic only','Unstructured'],'A','Decentralization speeds local decisions and responsiveness; centralization improves consistency and control.',SK),
  q(MOT,'According to Herzberg’s two-factor theory, salary and working conditions are:','Hygiene factors',['The main motivators for personal growth','Irrelevant to job satisfaction','Self-actualization needs'],'C','Herzberg found that hygiene factors prevent dissatisfaction, while motivators such as achievement, recognition and responsibility increase satisfaction.',BUCH),
  q(MOT,'Expectancy theory says employees are motivated when they believe that:','Effort leads to rewards they value',['Their basic needs are already met','Punishment will always be avoided','Their work is the same as everyone else’s'],'B','Vroom’s expectancy theory combines expectancy, instrumentality and valence. If any link is weak, motivation drops.',SK),
  q(MOT,'Two department heads work together to find a solution that fully meets both of their needs. Which conflict style is this?','Collaborating',['Avoiding','Accommodating','Competing'],'D','Collaborating seeks a win-win outcome. It takes time but builds commitment.',SK),
  q(MOT,'Each side in a scheduling dispute gives up part of what it wanted to reach an agreement. Which conflict style is this?','Compromising',['Collaborating','Avoiding','Competing'],'A','Compromise reaches a middle ground in which neither side fully wins. It is useful when time is short or both goals matter equally.',SK),
  q(MOT,'According to goal-setting theory, which goals tend to produce the highest performance?','Specific, challenging goals with feedback',['Vague goals such as “do your best”','Easy goals that everyone can meet','Goals that change daily without explanation'],'C','Clear, difficult but achievable goals, with commitment and feedback, improve performance more than vague goals.',SK),
  q(TEAM,'In Tuckman’s model, what is the correct order of team development stages?','Forming, storming, norming, performing',['Norming, forming, performing, storming','Storming, forming, norming, performing','Performing, norming, storming, forming'],'B','Teams first get acquainted (forming), work through conflict (storming), set norms (norming) and then work effectively (performing).',SK),
  q(TEAM,'A team rushes to agree with the leader’s plan, and members keep their doubts to themselves. What is this?','Groupthink',['Synergy','Social facilitation','Brainstorming'],'D','Groupthink occurs when the desire for harmony overrides critical thinking. Encouraging dissent and outside input helps prevent it.',SK),
  q(TEAM,'Which best describes an interprofessional care team?','Several professions sharing patient goals',['Employees from the same profession working alone','A team of administrators only','A group of patients sharing a room'],'A','Interprofessional teams, such as physicians, nurses, pharmacists and social workers, coordinate care and improve outcomes.',SK),
  q(TEAM,'Which evidence-based program was developed by AHRQ and the Department of Defense to improve teamwork and patient safety?','TeamSTEPPS',['Six Sigma','Lean','HCAHPS'],'C','TeamSTEPPS teaches communication, leadership, situation monitoring and mutual support skills.',SK),
  q(TEAM,'A team where members feel safe speaking up about mistakes without fear of blame has high:','Psychological safety',['Groupthink','High staff turnover','Span of control'],'B','Psychological safety encourages reporting errors and learning, which is essential for patient safety.',SK),
  q(COMM,'Information that spreads informally among employees outside official channels is called:','The grapevine',['Downward communication','A formal memo','A chain of command'],'D','The grapevine is fast and often partly accurate. Managers can reduce rumors with timely, transparent formal communication.',BUCH),
  q(COMM,'A manager listens without interrupting, asks clarifying questions and restates what the employee said. What is this skill?','Active listening',['Passive listening','Selective hearing','Downward communication'],'A','Active listening shows respect, improves understanding and reduces conflict.',BUCH),
  q(COMM,'A hospital CEO sends a policy announcement to all department managers. What direction of communication is this?','Downward communication',['Upward communication','Lateral communication','Diagonal communication'],'C','Downward communication flows from leaders to staff. Upward communication flows from staff to leaders, and lateral flows between peers.',BUCH),
  q(COMM,'A manager explains a budget change to front-desk staff using technical financial terms they do not understand. Which barrier is this?','Use of jargon',['Information overload from too few messages','Active listening','Two-way feedback'],'B','Jargon and technical language block understanding. Plain language suited to the audience improves communication.',BUCH),
  q(COMM,'Which structured tool is used across many hospitals to communicate concerns clearly between team members?','SBAR',['SWOT','PDSA','HCAHPS'],'D','SBAR (Situation, Background, Assessment, Recommendation) standardizes communication and reduces misunderstandings.',SK),
  q(QUAL,'What are the four steps of the PDSA cycle?','Plan, Do, Study, Act',['Prepare, Deliver, Survey, Adjust','Plan, Decide, Supervise, Approve','Predict, Design, Solve, Analyze'],'A','PDSA tests small changes, studies the results and adapts, supporting continuous improvement.',SK),
  q(QUAL,'Six Sigma quality improvement mainly aims to:','Reduce process variation and defects',['Increase the number of managers','Eliminate all staff training','Expand advertising'],'C','Six Sigma uses data and statistics, often through DMAIC (Define, Measure, Analyze, Improve, Control), to reduce errors.',SK),
  q(QUAL,'Lean management focuses on:','Eliminating non-value-added waste',['Adding more steps to every process','Hiring as many staff as possible','Increasing supply inventory on hand'],'B','Lean, based on the Toyota Production System, removes waste such as waiting, unnecessary motion and excess inventory.',SK),
  q(QUAL,'Donabedian’s model evaluates quality using which three elements?','Structure, process and outcome',['Cost, speed and volume','Mission, vision and values','Inputs, profits and marketing'],'D','Structure is resources and setting, process is what is done, and outcome is the result for patients.',SK),
  q(QUAL,'After a sentinel event, such as wrong-site surgery, what analysis looks for the underlying system causes?','Root cause analysis',['Break-even analysis','Market analysis','Payroll analysis'],'A','Root cause analysis focuses on systems and processes, not individual blame, so the event is less likely to happen again.',SK),
  q(STRAT,'A hospital lists its own strengths and weaknesses and the external opportunities and threats it faces. What tool is this?','SWOT analysis',['PDSA cycle','Gantt chart','Balanced budget'],'C','SWOT supports strategic planning by matching internal capabilities to external conditions.',BUCH),
  q(STRAT,'How does a vision statement differ from a mission statement?','Vision: desired future; mission: current purpose',['A vision lists budgets; a mission lists staff','They are identical','A mission describes the future; a vision describes the past'],'B','The mission states why the organization exists and whom it serves. The vision states what it hopes to become.',BUCH),
  q(STRAT,'Which tool measures performance across financial, customer, internal process and learning-and-growth perspectives?','Balanced scorecard',['SWOT analysis','Organizational chart','Fishbone diagram'],'D','The balanced scorecard links strategy to measurable goals beyond finances alone.',SK),
  q(STRAT,'During strategic planning, a hospital reviews population trends, competitors and new regulations. What is this step called?','Environmental scanning',['Root cause analysis','Benchmarking only','Credentialing'],'A','Environmental scanning identifies external trends that create opportunities or threats.',SK),
  q(STRAT,'Before opening a new clinic, administrators identify the groups affected and their interests. What is this?','Stakeholder analysis',['Payroll analysis','Inventory control','Cost shifting'],'C','Stakeholders, such as patients, physicians, community groups and payers, influence the success of a strategy.',SK),
  q(POL,'Which law requires hospital emergency departments to screen and stabilize patients regardless of ability to pay?','EMTALA',['HIPAA','The Stark Law','The Sherman Act'],'B','The Emergency Medical Treatment and Labor Act applies to hospitals that accept Medicare and prohibits “patient dumping.”',BUCH),
  q(POL,'The Stark Law restricts physicians from:','Self-referring to entities they own',['Prescribing generic drugs','Working in more than one hospital at once','Using electronic health records'],'D','Stark limits self-referral for certain services. The Anti-Kickback Statute separately prohibits payments for referrals.',BUCH),
  q(POL,'Which organization accredits most U.S. hospitals and conducts unannounced surveys?','The Joint Commission',['The American Medical Association','The FDA','The World Health Organization'],'A','Accreditation demonstrates compliance with quality and safety standards and is often linked to Medicare participation.',BUCH),
  q(POL,'Which major provision of the Affordable Care Act expanded coverage for low-income adults in states that adopted it?','Medicaid expansion',['Medicare Part D creation','The end of all private insurance','A ban on employer insurance'],'C','The ACA also created insurance marketplaces with subsidies and protected people with preexisting conditions.',BUCH),
  q(POL,'In some states, a hospital must get state approval before building a new facility or buying major equipment. What is this requirement?','Certificate of Need',['Certificate of Insurance','Medical license','Tax exemption'],'B','Certificate of Need laws aim to control costs by preventing unnecessary duplication of services.',BUCH),
  q(CONS,'Which standardized survey measures patients’ perspectives on their hospital care in the U.S.?','HCAHPS',['SWOT','PDSA','DMAIC'],'D','HCAHPS scores are publicly reported and affect Medicare payments through value-based purchasing.',SK),
  q(CONS,'Federal price transparency rules require hospitals to:','Publish standard and negotiated charges',['Charge every patient the same price','Stop billing all insurance companies','Hide prices until after treatment'],'A','Transparency helps consumers compare costs, though using the data can still be difficult.',BUCH),
  q(CONS,'A board member votes on a contract with a company she partly owns. What is the ethical problem?','A conflict of interest',['Groupthink','Vertical integration','Benchmarking'],'C','Conflicts of interest should be disclosed, and the person should step away from the decision.',BUCH),
  q(CONS,'Which hospital group advises on difficult ethical cases, such as end-of-life disagreements?','The ethics committee',['The finance committee','The marketing department','The billing office'],'B','Ethics committees include clinicians, administrators and community members who offer guidance to patients, families and staff.',BUCH),
  q(CONS,'A high-deductible health plan paired with a tax-advantaged savings account is an example of:','A consumer-driven plan',['A single-payer plan','Medicaid managed care coverage','A capitated HMO only'],'D','Consumer-driven plans give enrollees more financial responsibility and choice, using a health savings account (HSA) to pay for care.',BUCH)
 ],167)
};
